/* global console */
/**
 * Generates the injectable IIFE bundle (`dist/snapshot.iife.js`, global `MockupSnapshot`) and the module
 * `dist/inject.js`, which exports the same code as a string (`SNAPSHOT_SCRIPT`) for callers that inject via
 * `executeJavaScript` (desktop app).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dist = path.join(root, 'dist');
fs.mkdirSync(dist, { recursive: true });

const result = await build({
  entryPoints: [path.join(root, 'src/iife.ts')],
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['chrome110'],
  minify: true,
  legalComments: 'none',
  write: false,
});
const code = result.outputFiles[0].text;
fs.writeFileSync(path.join(dist, 'snapshot.iife.js'), code);
fs.writeFileSync(
  path.join(dist, 'inject.js'),
  `/** IIFE bundle code (defines globalThis.MockupSnapshot). Generated by scripts/build-bundle.mjs. */\nexport const SNAPSHOT_SCRIPT = ${JSON.stringify(code)};\n`,
);
fs.writeFileSync(
  path.join(dist, 'inject.d.ts'),
  '/** IIFE bundle code (defines globalThis.MockupSnapshot). */\nexport declare const SNAPSHOT_SCRIPT: string;\n',
);
console.log(`snapshot.iife.js ${(code.length / 1024).toFixed(1)} KB`);
